namespace QualityReporter.CSharp.Analysis;
public static class RecommendationEngine { public static void Generate(IEnumerable<FileResult> files){foreach(var f in files){var r=f.Recommendations;r.Clear();var evidence=new List<string>();if(f.Metrics.LineCoverage is double cov)evidence.Add($"Line Coverage: {cov:F0}%");if(f.Risk.ComplexityPercentile is double cp)evidence.Add($"Complexity: P{cp*100:F0}");if(f.Risk.ReworkPercentile is double rp)evidence.Add($"Rework: P{rp*100:F0}");if(f.Hotspot.Classifications.Contains("untested_complex")||f.Hotspot.Classifications.Contains("untested"))r.Add(new("ADD_TEST_BEFORE_REFACTOR",1,"Add characterization tests before changing this hotspot.",evidence));if(f.Hotspot.Classifications.Contains("duplicated"))r.Add(new("REVIEW_DUPLICATE_LOGIC",2,"Review whether duplicated fragments have the same business responsibility; if they do, consider extracting shared logic.",evidence));if(f.Hotspot.Classifications.Contains("complex")){var fn=f.Functions.MaxBy(x=>x.Complexity);r.Add(new("REDUCE_FUNCTION_COMPLEXITY",2,fn is null?"Split the highest-complexity responsibility.":$"Review and split {fn.Name} (complexity {fn.Complexity}).",evidence));}if(f.Hotspot.Classifications.Contains("rework"))r.Add(new("REVIEW_REWORK",3,"Review why this file is repeatedly changed and whether responsibilities or tests are insufficient.",evidence.Append($"Rework Rate: {f.History.ReworkRate:P0}").ToList()));if(f.Hotspot.Classifications.Contains("coupled")){var c=f.Couplings.MaxBy(x=>x.Ratio)!;r.Add(new("REVIEW_COUPLING",4,"Confirm that the coupled responsibility, API boundary, and shared model are intentional; separation is not automatically required.",evidence.Append($"Coupling with {c.CoupledWith}: {c.Ratio:P0}").ToList()));}if(f.Hotspot.Classifications.Contains("active")&&r.Count==0)r.Add(new("NO_ACTION_ACTIVE",9,"Actively developed; no immediate quality action is required.",new(){$"Activity: {f.Activity.EffectiveScore:F1}",$"Risk: {f.Risk.Score:F1}"}));}}}
